@@ -8,9 +8,27 @@ use crate::error::{BivvyError, Result};

 use super::{Prompt, PromptOption, PromptResult, PromptType};

-/// Convert dialoguer errors to BivvyError.
-fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
-    BivvyError::Io(e.into())
+/// Returns true if the key represents an EOF signal (Ctrl+D).
+fn is_eof_key(key: &Key) -> bool {
+    matches!(key, Key::Char('\x04'))
+}
+
+/// Wrap a dialoguer `interact_on` call with `catch_unwind` to convert
+/// internal panics (e.g., from terminal EOF during rendering) into IO errors.
+fn catch_dialoguer_panic<T, E>(
+    f: impl FnOnce() -> std::result::Result<T, E> + std::panic::UnwindSafe,
+) -> Result<T>
+where
+    E: Into<std::io::Error>,
+{
+    match std::panic::catch_unwind(f) {
+        Ok(Ok(val)) => Ok(val),
+        Ok(Err(err)) => Err(BivvyError::Io(err.into())),
+        Err(_payload) => Err(BivvyError::Io(std::io::Error::new(
+            std::io::ErrorKind::Interrupted,
+            "prompt aborted (terminal EOF)",
+        ))),
+    }
 }

 /// Dialoguer theme without the default yellow `?` prefix.
@@ -66,26 +84,30 @@ fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
         .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
         .unwrap_or(true);

